python3 - <<'PYEOF'
import re
p = 'guide/design.md'
s = open(p).read()

# Prefix each "In ivue" cell with a check badge. Rows are the 8 problem rows:
# split each table row into cells and prepend the badge to the 3rd cell.
lines = s.split('\n')
out = []
in_table = False
for ln in lines:
    if ln.startswith('| Problem |'):
        in_table = True
        out.append(ln)
        continue
    if in_table:
        if ln.startswith('|---'):
            out.append(ln)
            continue
        if ln.startswith('| **'):
            cells = ln.split(' | ')
            # cells[0] starts with '| ', last ends with ' |'
            if len(cells) == 3:
                cells[2] = '<span class="iv-ck" aria-hidden="true"></span> ' + cells[2]
                ln = ' | '.join(cells)
            out.append(ln)
            continue
        in_table = False
    out.append(ln)
s = '\n'.join(out)
open(p, 'w').write(s)
print('badges added:', s.count('iv-ck'))
PYEOF

