// TEMP verification spec — deleted after the DemoInheritance rewrite is confirmed.
import { describe, expect, it } from 'vitest';
import { mount } from '@vue/test-utils';
import { nextTick } from 'vue';
import DemoInheritance from '../../docs_v2/.vitepress/theme/components/DemoInheritance.vue';
import { Product } from '../../docs_v2/.vitepress/theme/components/pricing/product';
import { SaleProduct } from '../../docs_v2/.vitepress/theme/components/pricing/sale-product';
import { TaxedProduct } from '../../docs_v2/.vitepress/theme/components/pricing/taxed-product';

describe('pricing chain (inheritance.md example)', () => {
  it('chains total and receipt through three levels', () => {
    const product = new TaxedProduct.Class();
    expect(product.total).toBeCloseTo(42.24, 10);
    expect(product.receipt()).toEqual([
      'Mechanical keyboard — $48.00',
      'sale −20%',
      'tax +10%',
      'due — $42.24',
    ]);

    product.price.value = 60; // grandparent ref
    expect(product.total).toBeCloseTo(52.8, 10);

    product.discount.value = 0.5; // middle level
    expect(product.total).toBeCloseTo(33, 10);
  });

  it('middle level is a complete class of its own', () => {
    const saleProduct = new SaleProduct.Class();
    expect(saleProduct.total).toBeCloseTo(38.4, 10);
    expect(saleProduct.receipt()).toHaveLength(2);
  });

  it('base level stands alone', () => {
    const product = new Product.Class();
    expect(product.total).toBe(48);
    expect(product.receipt()).toEqual(['Mechanical keyboard — $48.00']);
  });

  it('DemoInheritance mounts, renders the receipt, and re-renders on every level', async () => {
    const wrapper = mount(DemoInheritance);
    expect(wrapper.text()).toContain('Mechanical keyboard — $48.00');
    expect(wrapper.text()).toContain('due — $42.24');
    expect(wrapper.text()).toContain('$42.24'); // total chip

    const buttons = wrapper.findAll('button');
    expect(buttons).toHaveLength(3);

    await buttons[0].trigger('click'); // price +$6 → 54 × 0.8 × 1.1 = 47.52
    await nextTick();
    expect(wrapper.text()).toContain('$54');
    expect(wrapper.text()).toContain('due — $47.52');

    await buttons[1].trigger('click'); // discount 0.25 → 54 × 0.75 × 1.1 = 44.55
    await nextTick();
    expect(wrapper.text()).toContain('sale −25%');
    expect(wrapper.text()).toContain('due — $44.55');

    await buttons[2].trigger('click'); // tax off → 54 × 0.75 = 40.50
    await nextTick();
    expect(wrapper.text()).toContain('tax +0%');
    expect(wrapper.text()).toContain('due — $40.50');
  });
});

