    md.core.ruler.after('inline', 'task-lists', (state) => {
      const tokens = state.tokens;
      for (let i = 2; i < tokens.length; i++) {
        const token = tokens[i];
        if (
          token.type !== 'inline' ||
          !token.children?.length ||
          tokens[i - 1].type !== 'paragraph_open' ||
          tokens[i - 2].type !== 'list_item_open'
