    expect(pointer.x.value).toBeTypeOf('number');
    expect(pointer.x).toBe(pointer.x); // cached ref, stable identity
    window.dispatchEvent(
      new MouseEvent('mousemove', { clientX: 120, clientY: 80 }),
    );
    expect(pointer.x.value).toBe(120);
    expect(pointer.y.value).toBe(80);
  });

  it('DemoPointer mounts and re-renders on mouse movement', async () => {
    const wrapper = mount(DemoPointer, { attachTo: document.body });
    window.dispatchEvent(
      new MouseEvent('mousemove', { clientX: 321, clientY: 45 }),
    );
    await nextTick();
    expect(wrapper.text()).toContain('321');
    expect(wrapper.text()).toContain('45');
    wrapper.unmount();
  });
});

