import pathlib
p = pathlib.Path('docs_v2/.vitepress/theme/custom.css')
text = p.read_text()

old = """/* Quote */
.ix-quote {
  text-align: center;
  max-width: 46rem;
  margin: 0 auto;
}
.ix-quote::before {
  content: '';
  display: block;
  width: 56px;
  height: 2px;
  margin: 0 auto 40px;
  border-radius: 2px;
  background: var(--ivue-grad);
}
.ix-quote blockquote {
  border: none;
  margin: 0;
  padding: 0;
  font-size: clamp(1.35rem, 2.8vw, 1.8rem);
  font-weight: 320;
  line-height: 1.5;
  letter-spacing: -0.012em;
  color: var(--vp-c-text-1);
}
.ix-quote cite {
  display: block;
  margin-top: 22px;
  font-style: normal;
  font-size: 0.92rem;
  color: var(--vp-c-text-3);
}"""

new = """/* Quote */
.ix-quote {
  text-align: center;
  max-width: 48rem;
  margin: 0 auto;
}
.ix-quote::before {
  content: '\\201C';
  display: block;
  height: 54px;
  margin: 0 auto 8px;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 88px;
  line-height: 1.08;
  background: var(--ivue-grad-text);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.ix-quote blockquote {
  border: none;
  margin: 0;
  padding: 0;
  font-family: Georgia, 'Times New Roman', serif;
  font-style: italic;
  font-size: clamp(1.45rem, 3vw, 1.95rem);
  font-weight: 400;
  line-height: 1.45;
  letter-spacing: -0.008em;
  color: var(--vp-c-text-1);
}
.ix-quote cite {
  display: block;
  margin-top: 20px;
  font-style: normal;
  font-size: 0.82rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--vp-c-text-3);
}
.ix-quote cite::before {
  content: '\\2014\\00A0';
}
/* the quote holds the room; the next section sits a little closer */
.ix section.ix-quote + section {
  padding-top: 56px;
}
@media (min-width: 768px) {
  .ix section.ix-quote + section {
    padding-top: 72px;
  }
}"""

assert old in text
p.write_text(text.replace(old, new))
print("OK")
EOF

